from playwright.sync_api import sync_playwright
import os
BASE=os.environ.get('BLACKLINE_TEST_URL','http://127.0.0.1:8044')
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox'])
 for mode,map_id,interior,transport in [('guard','urban-modern-north','office','ground'),('interior','urban-quarter-north','office-north','ground'),('rescue','mountain','clinic','helicopter')]:
  page=b.new_page(viewport={'width':844,'height':390},is_mobile=True,has_touch=True);errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
  page.goto(BASE,wait_until='networkidle');page.locator('#blackline-continue').click()
  page.evaluate('''cfg=>{state.simClock.paused=true;state.cash=2e9;state.ammo=20000;state.med=100;state.operations=[];state.history=[];state.team=Array.from({length:8},(_,i)=>({id:401+i,name:'통합대원'+i,role:['팀장','의무','정찰','전투','지원','저격수','전투','전투'][i],skill:90,country:'대한민국',unit:'가상 부대',rank:'중사',birthDate:'1995-01-01',salary:6e7,loadout:{primary:'미지급'}}));blacklineReviewArmory();blacklineReviewTransport();const m={...state.missions[0],id:19001,title:'통합 검증 '+cfg.mode,type:cfg.mode==='rescue'?'구조':'시설 보안',risk:1,mapId:cfg.map_id,pinMap:true,objectiveMode:cfg.mode,interiorId:cfg.interior,transport:cfg.transport,reward:2e7},op={id:'AUDIT-'+cfg.mode,missionId:m.id,leaderId:401,leaderName:'통합대원0',status:'현장 진행 중',budget:6e7,contract:m,air:'off',artillery:'off',teamIds:state.team.map(p=>p.id),fieldProgress:{stage:0,seed:25,startedDay:state.day,startedDate:state.date,riskShift:0,lateRisk:0,events:[],supportOrders:[]}};state.operations=[op];if(!blacklineReserveTransport(op,cfg.transport))throw Error('transport missing');const ammo=fieldSimulation.ammoPlan(state.team).total;state.ammo-=ammo;state.med-=12;op.fieldProgress.reservedTacticalAmmo=ammo;op.fieldProgress.reservedTacticalMed=12;const s=fieldSimulation.create(op,m,state.team,ammo,{forceContact:false,medicalBudget:12});s.units=s.units.filter(u=>u.faction==='blackline');op.fieldProgress.tactical=s;window.auditOp=op;let wounded=false;for(let i=0;i<7000&&!s.done;i++){fieldSimulation.step(s,op);if(!wounded&&s.journey.stage==='site'){const u=s.units.find(u=>u.personId===401);fieldSimulation.applyWound(s,u,10,null,'leftArm');wounded=true;}}if(!s.done||s.journey.stage!=='complete'||s.objective<100)throw Error('mission stuck '+JSON.stringify({mode:cfg.mode,stage:s.journey.stage,phase:s.phase,objective:s.objective,units:s.units.map(u=>({id:u.id,status:u.status,x:u.x,y:u.y,inside:u.inside,p:u.interior}))}));const ledger=fieldSimulation.ammoAccounting(s,op);if(ledger.issued!==ledger.fired+ledger.returned+ledger.lost)throw Error('ammo nonconservation');window.auditExpected={ammo:state.ammo+ledger.returned,med:state.med+12-s.medUsed,cost:op.fieldProgress.reservedSupportCost,asset:op.transportPlan.assetId};openFieldObservation(op.id);blacklineReviewCompany=()=>{};blacklineReviewHR=()=>{};nextDay();state.simClock.paused=false;}''',{'mode':mode,'map_id':map_id,'interior':interior,'transport':transport})
  page.wait_for_function("auditOp.status==='작전 완료'",timeout=15000)
  data=page.evaluate('''()=>{state.simClock.paused=true;const op=auditOp,p=state.team.find(p=>p.id===401);if(state.history.filter(h=>h.planId===op.id).length!==1)throw Error('duplicate history');if(state.ammo!==auditExpected.ammo||state.med!==auditExpected.med)throw Error('stock settlement mismatch '+JSON.stringify({ammo:state.ammo,med:state.med,expected:auditExpected}));if(!p.injured||!p.medicalCase||p.awaitingRecovery||p.injuryHistory.length!==1)throw Error('returned injury not admitted');if(op.actualSupportCost!==auditExpected.cost)throw Error('transport/support ledger mismatch');if(state.transportFleet.find(a=>a.id===auditExpected.asset).reservation)throw Error('asset not released');const value={history:state.history.length,ammo:state.ammo,med:state.med,cash:state.cash};save();blacklineFlushSave();return value;}''')
  page.reload(wait_until='networkidle');page.locator('#blackline-continue').click()
  assert page.evaluate('state.history.length')==data['history'];assert page.evaluate('state.ammo')==data['ammo'];assert page.evaluate('state.med')==data['med'];assert not errors,errors
  print('PASS',mode,map_id,transport,'physical success/return, wound admission, exact ammunition/medical/fuel settlement, single history and reload')
  page.close()
 b.close()
